//! Differential parity against the real TS engine (`fixtures/trace.json`,
//! generated by `scripts/gen-fixtures.ts`): 71 `GameState`s sampled from three
//! real matches, covering every phase, loners, sitting seats, throw-ins, the
//! natural-trump house rule and game over.
//!
//! For each sample the port must, byte for byte (key order included):
//! * round-trip the persisted `GameState` JSON,
//! * reproduce `project(state, seat)` for all four seats (legal moves included),
//! * reproduce `applyOptimistic(view, move)` for every legal move of the actor,
//! * round-trip the transition's raw `Step[]` and reproduce `projectSteps` per seat.

use euchre_engine::{
    GameState, Move, PublicGameView, Seat, Step, apply_optimistic, project, project_steps,
};
use serde_json::Value;

const TRACE_JSON: &str = include_str!("fixtures/trace.json");

fn samples() -> Vec<Value> {
    let v: Value = serde_json::from_str(TRACE_JSON).unwrap_or(Value::Null);
    v["samples"].as_array().cloned().unwrap_or_default()
}

fn parse<T: serde::de::DeserializeOwned>(v: &Value, what: &str) -> T {
    serde_json::from_value(v.clone()).unwrap_or_else(|e| panic!("{what}: {e}\n{v}"))
}

/// Compact JSON with the fixture's (TS) key order preserved.
fn json(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

fn ours<T: serde::Serialize>(x: &T) -> String {
    serde_json::to_string(x).unwrap_or_default()
}

fn label(s: &Value) -> &str {
    s["label"].as_str().unwrap_or("?")
}

#[test]
fn fixture_covers_every_phase_and_the_loner_and_throw_in_paths() {
    let all = samples();
    assert_eq!(all.len(), 71);
    let mut phases: Vec<&str> = all
        .iter()
        .filter_map(|s| s["state"]["hand"]["phase"].as_str())
        .collect();
    phases.sort_unstable();
    phases.dedup();
    assert_eq!(phases.len(), 9, "{phases:?}"); // every phase but the transient `deal`
    assert!(
        all.iter()
            .any(|s| !s["state"]["hand"]["sittingSeat"].is_null())
    );
    let has_step = |t: &str| {
        all.iter().any(|s| {
            s["steps"]
                .as_array()
                .is_some_and(|st| st.iter().any(|x| x["t"] == t))
        })
    };
    for t in [
        "cut",
        "dealt",
        "upCardTurned",
        "bid",
        "turnedDown",
        "trumpSet",
        "dealerDiscarded",
        "cardPlayed",
    ] {
        assert!(has_step(t), "{t}");
    }
    for t in ["trickWon", "handScored", "throwIn", "gameWon"] {
        assert!(has_step(t), "{t}");
    }
}

#[test]
fn game_state_json_round_trips_byte_for_byte() {
    for s in samples() {
        let state: GameState = parse(&s["state"], label(&s));
        assert_eq!(ours(&state), json(&s["state"]), "{}", label(&s));
    }
}

#[test]
fn project_matches_ts_for_every_seat() {
    let mut checked = 0;
    for s in samples() {
        let state: GameState = parse(&s["state"], label(&s));
        let views = s["views"].as_array().cloned().unwrap_or_default();
        assert_eq!(views.len(), 4, "{}", label(&s));
        for seat in Seat::ALL {
            let view = project(&state, seat);
            assert_eq!(
                ours(&view),
                json(&views[seat.index()]),
                "{} seat {seat}",
                label(&s)
            );
            // And the TS view deserializes into the same Rust value.
            let theirs: PublicGameView = parse(&views[seat.index()], label(&s));
            assert_eq!(theirs, view, "{} seat {seat}", label(&s));
            checked += 1;
        }
    }
    assert_eq!(checked, 71 * 4);
}

#[test]
fn apply_optimistic_matches_ts_for_every_legal_move() {
    let mut checked = 0;
    for s in samples() {
        let state: GameState = parse(&s["state"], label(&s));
        let rows = s["optimistic"].as_array().cloned().unwrap_or_default();
        let Some(turn) = state.hand.turn_seat else {
            assert!(rows.is_empty(), "{}", label(&s));
            continue;
        };
        let view = project(&state, turn);
        assert_eq!(rows.len(), view.legal.len(), "{}", label(&s));
        for (row, lm) in rows.iter().zip(&view.legal) {
            assert_eq!(
                row["moveId"].as_str(),
                Some(lm.id.as_str()),
                "{}",
                label(&s)
            );
            let seat: Seat = parse(&row["seat"], label(&s));
            assert_eq!(seat, turn);
            let mv: Move = lm.mv;
            let got = apply_optimistic(&view, &mv);
            assert_eq!(ours(&got), json(&row["view"]), "{} {}", label(&s), lm.id);
            checked += 1;
        }
    }
    assert!(checked > 150, "only {checked} optimistic checks");
}

#[test]
fn steps_round_trip_and_project_steps_redacts_like_ts() {
    let mut checked = 0;
    for s in samples() {
        if s["steps"].is_null() {
            assert!(s["projectedSteps"].is_null(), "{}", label(&s));
            continue;
        }
        let steps: Vec<Step> = parse(&s["steps"], label(&s));
        assert_eq!(ours(&steps), json(&s["steps"]), "{}", label(&s));
        let projected = s["projectedSteps"].as_array().cloned().unwrap_or_default();
        assert_eq!(projected.len(), 4, "{}", label(&s));
        for seat in Seat::ALL {
            assert_eq!(
                ours(&project_steps(&steps, seat)),
                json(&projected[seat.index()]),
                "{} seat {seat}",
                label(&s)
            );
            checked += 1;
        }
    }
    assert_eq!(checked, 68 * 4);
}

#[test]
fn project_steps_never_leaks_a_foreign_dealt_packet() {
    for s in samples() {
        let Ok(steps) = serde_json::from_value::<Vec<Step>>(s["steps"].clone()) else {
            continue;
        };
        for seat in Seat::ALL {
            for step in project_steps(&steps, seat) {
                if let Step::Dealt { packets } = step {
                    for p in packets {
                        assert_eq!(p.cards.is_some(), p.seat == seat, "{}", label(&s));
                    }
                }
            }
        }
    }
}

#[test]
fn views_never_carry_foreign_cards() {
    // V12: the only card lists in a view are your own hand, public tricks, and the up-card.
    for s in samples() {
        let state: GameState = parse(&s["state"], label(&s));
        for seat in Seat::ALL {
            let view = project(&state, seat);
            for other in Seat::ALL {
                if other == seat {
                    continue;
                }
                for card in &state.hand.hands[other.index()] {
                    assert!(
                        !view.hand.contains(card),
                        "{} seat {seat} sees {card}",
                        label(&s)
                    );
                }
            }
            if Some(seat) == state.hand.sitting_seat {
                assert!(view.hand.is_empty());
                assert_eq!(view.hand_counts[seat.index()], 0);
            }
        }
    }
}
